Cada tarea es un índice, y cada goroutine escribe solo en su posición, así que no hay carreras de datos aunque compartan el slice de salida. Cerrar el canal indica a los trabajadores que no habrá más tareas, y `WaitGroup` espera a que acaben.

```go
func SquareAll(nums []int, workers int) []int {
	if workers < 1 {
		workers = 1
	}
	out := make([]int, len(nums))
	jobs := make(chan int)
	var wg sync.WaitGroup
	for w := 0; w < workers; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for i := range jobs {
				out[i] = nums[i] * nums[i]
			}
		}()
	}
	for i := range nums {
		jobs <- i
	}
	close(jobs)
	wg.Wait()
	return out
}
```

